// Lista de eventids dos problemas (["0"] quando não há problema, para não virar consulta sem filtro)
const r = $json.result;
if (!Array.isArray(r)) throw new Error('Zabbix problem.get falhou: ' + JSON.stringify($json.error || $json));
const ids = r.map(p => p.eventid);
return [{ json: { eventids: ids.length ? ids : ['0'] } }];

// hostids e nomes para host.get e NetBox
const r = $json.result;
if (!Array.isArray(r)) throw new Error('Zabbix event.get falhou: ' + JSON.stringify($json.error || $json));
const hostids = new Set(), nomes = new Set();
for (const e of r) for (const h of (e.hosts || [])) { hostids.add(h.hostid); nomes.add(h.host); nomes.add(h.name); }
return [{ json: { hostids: hostids.size ? [...hostids] : ['0'], nomes: nomes.size ? [...nomes] : ['__nenhum__'] } }];

// Monta o resumo do NOC. Tudo calculado aqui: o agente só apresenta e comenta.
const TZ = 'America/Fortaleza';
const SEV = { 0: 'Não classificada', 1: 'Informação', 2: 'Atenção', 3: 'Média', 4: 'Alta', 5: 'Desastre' };
const ST = { 1: 'Novo', 2: 'Em atendimento (atribuído)', 3: 'Em atendimento (planejado)', 4: 'Pendente' };
const fmt = (d) => d.toLocaleString('pt-BR', { timeZone: TZ, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }).replace(',', '');

const problemas = $('Zabbix - problem.get').first().json.result || [];
const eventos = $('Zabbix - event.get').first().json.result || [];
const hosts = $('Zabbix - host.get').first().json.result || [];
const nb = $('NetBox - devices').first().json;
const gl = $('GLPI - chamados abertos').first().json;

// Índices
const hostDoEvento = {};
for (const e of eventos) hostDoEvento[e.eventid] = (e.hosts || [])[0] || null;
const hostPorId = {};
for (const h of hosts) hostPorId[h.hostid] = h;
const nbPorNome = {};
const netboxOk = Array.isArray(nb.results);
for (const d of (nb.results || [])) nbPorNome[String(d.name).toLowerCase()] = d;

// Chamados abertos (status 1-4) vindos do GLPI
const glpiOk = Array.isArray(gl.data) || gl.totalcount === 0;
const chamados = (gl.data || []).map(r => ({
  id: Number(r['2']), titulo: r['1'], status: Number(r['12']),
  aberto_em: r['15'] ? `${r['15'].slice(8, 10)}/${r['15'].slice(5, 7)} ${r['15'].slice(11, 16)}` : null,
  categoria: r['7'] || null,
})).filter(c => c.status >= 1 && c.status <= 4);
const chamadoPorId = {};
for (const c of chamados) chamadoPorId[c.id] = c;

const usados = new Set();
const lista = problemas.map(p => {
  const hb = hostDoEvento[p.eventid] || {};
  const h = hostPorId[hb.hostid] || hb;
  const d = nbPorNome[String(h.host || '').toLowerCase()] || nbPorNome[String(h.name || '').toLowerCase()];
  const tag = (p.tags || []).find(t => t.tag === '__zbx_glpi_ticket_id');
  const idTag = tag ? Number(tag.value) : null;
  let chamado = null;
  if (idTag && chamadoPorId[idTag]) {
    const c = chamadoPorId[idTag]; usados.add(c.id);
    chamado = { id: c.id, status: ST[c.status], aberto_em: c.aberto_em };
  } else if (idTag) {
    chamado = { id: idTag, status: 'não está aberto no GLPI (ou sem permissão de leitura)' };
  }
  const ip = (h.interfaces || []).find(i => i.main === '1')?.ip || null;
  return {
    evento: p.eventid,
    host: h.name || h.host || 'desconhecido',
    ip,
    problema: p.name,
    severidade: SEV[p.severity] || p.severity,
    sev: Number(p.severity),
    desde: fmt(new Date(Number(p.clock) * 1000)),
    reconhecido: p.acknowledged === '1',
    em_manutencao: p.suppressed === '1' || h.maintenance_status === '1',
    site: d?.site?.name || null,
    funcao: (d?.role || d?.device_role)?.name || null,
    netbox: d ? 'cadastrado' : (netboxOk ? 'não cadastrado no NetBox' : 'NetBox indisponível'),
    chamado,
  };
});

// Sinalizações
const porSite = {};
for (const x of lista) if (x.site) (porSite[x.site] ||= new Set()).add(x.host);
const causa_comum = Object.entries(porSite).filter(([, s]) => s.size >= 2).map(([site, s]) => ({ site, hosts: [...s] }));
const alta_sem_chamado = lista.filter(x => x.sev >= 4 && !x.em_manutencao && !(x.chamado && x.chamado.status && !x.chamado.status.startsWith('não'))).map(x => x.host);
const chamados_sem_problema = chamados.filter(c => !usados.has(c.id) && /alerta de monitoramento/i.test(c.categoria || '')).map(c => ({ id: c.id, titulo: c.titulo, status: ST[c.status] }));
const em_manutencao = lista.filter(x => x.em_manutencao).map(x => x.host);

const total = {};
for (const x of lista) total[x.severidade] = (total[x.severidade] || 0) + 1;

return [{ json: {
  gerado_em: fmt(new Date()),
  fontes: { zabbix: 'ok', netbox: netboxOk ? 'ok' : 'falhou', glpi: glpiOk ? 'ok' : ('falhou: ' + JSON.stringify(gl).slice(0, 200)) },
  total_problemas: lista.length,
  por_severidade: total,
  chamados_abertos_glpi: chamados.length,
  problemas: lista.map(({ sev, ...r }) => r),
  sinalizacoes: { causa_comum, alta_sem_chamado, chamados_sem_problema, em_manutencao },
} }];
